const posts = await Post.findAll({ limit: 200 });   // 쿼리 1개
for (const p of posts) {
  const author = await p.getUser();   // 반복마다 쿼리 1개씩 = 200개
  render(p.title, author.name);
}
// 총 201개. 코드는 자연스러워 보이는데 로그는 폭발한다.

// ① 미리 함께 가져오기 (eager loading) — 조인 한 방
await Post.findAll({ include: [User], limit: 200 });

// ② 자식을 IN 으로 한 번에 (2 쿼리) — 4장
const posts = await Post.findAll({ limit: 200 });
const ids = posts.map(p => p.userId);
const users = await User.findAll({ where: { id: ids } });  // IN (...)

// ③ DataLoader 로 요청 내 자동 배치 — 접근은 그대로, 뒤에서 IN 으로 묶음

