db.on('query', () => count++);         // 모든 쿼리를 센다

test('GET /posts 는 쿼리 15개 이하', async () => {
  count = 0;
  await request(app).get('/posts?limit=200');
  expect(count).toBeLessThan(15);       // 넘으면 실패 -> N+1 회귀 차단
});
